package com.bananalab.lite;
import java.nio.file.*;import java.util.*;import org.json.*;
public final class Stage74SourceExercisesCheck{
 static void check(boolean v,String why){if(!v)throw new AssertionError(why);}
 public static void main(String[] args)throws Exception{Path root=Paths.get(args[0]);BananaTransformer model=Stage56TrainingCheck.model(root);NotebookDisk.Doc doc=new NotebookDisk.Doc();doc.id=JavaMethodEditor.hash("own");doc.sha=JavaMethodEditor.hash("La sal es un sabor.");doc.source="https://example.com/own";doc.origin="web";doc.title="Ejercicios";String text="La sal es un sabor.";List<JSONObject> rows=SourceExercises.create(model,doc,text,0);check(rows.size()==3,"definition, completion and reverse exercises");for(JSONObject row:rows){check(row.getString("sourceSha256").equals(doc.sha)&&row.getString("evidence").contains(row.getString("answer")),"literal label and source provenance");check(!row.getString("question").equals(row.getString("evalQuestion")),"separate heldout formulation");}check(!SourceExercises.choose(rows,1,0).getString("id").equals(SourceExercises.choose(rows,2,0).getString("id")),"spaced rounds vary the exercise");ReadingWeights.Batch batch=SourceExercises.batch(model,doc,text,0,0,1);JSONObject attempt=SourceExercises.attempt(model,batch.exercise,new ReadingWeights.Governor(){public void check(){}});check(attempt.getString("labelOrigin").equals("literal_source_not_model")&&attempt.getString("answer").equals(batch.exercise.getString("answer"))&&attempt.getInt("attemptTokens")<=12,"bounded self answer never overwrites source label");JSONObject report=ReadingWeights.fit(model,Stage56TrainingCheck.model(root),batch,new ReadingWeights.Governor(){public void check(){}},true);check(report.getBoolean("accepted")&&report.getInt("epochs")==1&&report.getBoolean("microBatch"),"actual micro SGD and retained validation "+report);report.put("exercise",attempt);CreatorPersistenceCheck.Fake c=new CreatorPersistenceCheck.Fake();for(int i=0;i<15;i++)LearningLoop.result(c,report);JSONObject saved=LearningLoop.portable(c);LearningLoop.validate(saved);check(saved.getJSONArray("history").length()==12&&saved.getInt("accepted")==15,"bounded exercise history with real attempts");Files.write(root.resolve("test/resources/continuous66-report.json"),report.toString(2).getBytes("UTF-8"));System.out.println("PASS source-exact exercises, bounded independent attempts, own-model micro training and portable history "+report);}
}
